fun recover(): RecoveryReport {
    val committed = mutableListOf<String>()
    val rolledBack = mutableListOf<String>()
    for (p in participants) {
        val suffix = "@${p.name}"
        for (gid in p.preparedGids().filter { it.endsWith(suffix) }) {   // only our branches
            if (log.committed(gid.removeSuffix(suffix))) {
                p.exec("COMMIT PREPARED '$gid'"); committed += gid      // decided: finish it
            } else {
                p.exec("ROLLBACK PREPARED '$gid'"); rolledBack += gid   // presumed abort
            }
        }
    }
    return RecoveryReport(committed, rolledBack)
}

