fun run(txId: String, work: Map<String, List<String>>): Outcome {
    val prepared = mutableListOf<Participant>()
    for (p in participants) {                                   // phase one: everyone votes
        try {
            p.exec("BEGIN")
            work[p.name].orEmpty().forEach { p.exec(it) }
            p.exec("PREPARE TRANSACTION '${p.gid(txId)}'")      // yes: durable, locks kept
            prepared += p
        } catch (e: SQLException) {                             // no: abort everyone
            p.exec("ROLLBACK")
            prepared.forEach { it.exec("ROLLBACK PREPARED '${it.gid(txId)}'") }
            return Outcome.Aborted(p.name, e.sqlState)          // no log line: presumed abort
        }
    }
    log.recordCommit(txId)                                      // fsync'd: the commit point
    for (p in participants) p.exec("COMMIT PREPARED '${p.gid(txId)}'")   // phase two, retried in real life
    return Outcome.Committed
}

// The commit point is the flushed log line. It must come first: if a COMMIT PREPARED went out
// and then the line was lost in a crash, recovery would find no decision and roll back the
// other participant, leaving half a transfer.
